/* ===================== Design tokens ===================== */
:root {
  /* Fresh & Minimal skin (design direction #6). Token NAMES are kept so the
     existing rules keep resolving; VALUES retuned to a clean, modern
     violet-on-white theme. --serif now holds a sans (Plus Jakarta Sans) — the
     name is a historical hook, not a promise of a serif face. */
  --red: #6c4cf1;        /* primary action — violet */
  --red-dark: #5a3fd6;
  --gold: #6c4cf1;       /* selection / focus accent — violet */
  --blue: #6c4cf1;       /* destination / user pin — violet */
  --blue-dark: #5a3fd6;
  --pink: #ef4444;       /* warning red — debug chip only */
  --ink: #101828;        /* near-black */
  --paper: #ffffff;      /* card surface */
  --bg: #f7f8fa;         /* page background */
  --muted: #667085;
  --line: #eaecf0;
  --yellow-badge: #f4d645;
  --ok: #059669;         /* success / "fits" — Fresh green (accents, borders) */
  --ok-text: #047857;    /* success text — darker for AA contrast on white/tint */
  --ok-bg: #e6f7ee;      /* success badge background */
  --shadow-soft: 0 12px 30px rgba(16, 24, 40, 0.08);
  --shadow-offset: 6px;
  --maxw: 1120px;
  --radius: 16px;
  --serif: "Plus Jakarta Sans", "Plus Jakarta Sans Fallback", system-ui, sans-serif;
  font-synthesis: none;
}

/* Metric-matched fallback faces. Until the web fonts arrive, text is laid out
   in local Arial *stretched to the web font's own metrics* (size-adjust +
   ascent/descent overrides), so the swap to Inter / Plus Jakarta Sans reflows
   almost nothing — this is what keeps CLS out of the "needs improvement" band.
   Override values are the standard next/font-generated set for each family. */
@font-face {
  font-family: "Inter Fallback";
  src: local("Arial");
  size-adjust: 107.40%;
  ascent-override: 90.20%;
  descent-override: 22.48%;

