// Drive the Now page's "Not a show? Type a place" flow in real Chromium.
// External hosts are blocked in this sandbox, so every third-party request is
// route-intercepted: Leaflet from the local npm copies, tiles/fonts aborted,
// and Nominatim answered from the SAME committed fixtures the unit tests use —
// so the browser exercises the shipped fetch path deterministically.
import { chromium } from "playwright-core";
import { readFileSync } from "node:fs";

const REPO = "/home/user/EdFringeNow";
const SCRATCH = "/tmp/claude-0/-home-user-EdFringeNow/61bd45c2-d6e6-548c-a167-be9f0ac03147/scratchpad";
const fixture = (n) => readFileSync(`${REPO}/js/__tests__/fixtures/nominatim/${n}.json`, "utf8");

const browser = await chromium.launch({
  executablePath: "/opt/pw-browsers/chromium-1194/chrome-linux/chrome",
  args: ["--no-sandbox"],
});
const page = await browser.newPage({ viewport: { width: 480, height: 1000 } });
page.setDefaultTimeout(15000);

const local = {
  "leaflet@1.9.4/dist/leaflet.js": `${SCRATCH}/node_modules/leaflet/dist/leaflet.js`,
  "leaflet@1.9.4/dist/leaflet.css": `${SCRATCH}/node_modules/leaflet/dist/leaflet.css`,
  "leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js": `${SCRATCH}/node_modules/leaflet.markercluster/dist/leaflet.markercluster.js`,
  "leaflet.markercluster@1.5.3/dist/MarkerCluster.css": `${SCRATCH}/node_modules/leaflet.markercluster/dist/MarkerCluster.css`,
};
await page.route("https://unpkg.com/**", (route) => {
  const hit = Object.entries(local).find(([k]) => route.request().url().includes(k));
  if (!hit) return route.abort();
  const type = hit[0].endsWith(".css") ? "text/css" : "application/javascript";
  route.fulfill({ body: readFileSync(hit[1], "utf8"), contentType: type });
});
await page.route("https://fonts.googleapis.com/**", (r) => r.abort());
await page.route("https://fonts.gstatic.com/**", (r) => r.abort());
await page.route("https://*.tile.openstreetmap.org/**", (r) => r.abort());
await page.route("https://nominatim.openstreetmap.org/search*", (route) => {
  const q = new URL(route.request().url()).searchParams.get("q") || "";
  const body = /brewdog/i.test(q) ? fixture("brewdog")
    : /waverley/i.test(q) ? fixture("edinburgh-waverley")
    : fixture("zzzqqqxyzzy");
  route.fulfill({ body, contentType: "application/json" });
});

page.on("pageerror", (e) => { console.error("PAGE ERROR:", e.message); process.exitCode = 1; });

await page.goto("http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8099/", { waitUntil: "networkidle" });
await page.waitForSelector(".cta-trigger");

const check = async (name, cond) => {
  if (!(await cond())) { console.error(`FAIL: ${name}`); process.exitCode = 1; }
  else console.log(`ok: ${name}`);
};

// --- multi-candidate flow: BrewDog (4 pubs) ---
await page.click(".cta-trigger");
await page.fill("#destInput", "BrewDog");
await page.click("#destFind");
await page.waitForSelector("#destResults .place-hit");
await check("4 candidates + note row", async () => (await page.$$("#destResults .place-hit")).length === 5);
await check("candidate rows carry the street", async () =>
  (await page.textContent("#destResults")).includes("Lothian Road"));
await page.screenshot({ path: `${SCRATCH}/shot-1-candidates.png` });

await page.click('#destResults .place-hit[data-i="1"]'); // BrewDog Lothian Road
await page.waitForSelector("#journeyStrip .plan-node.dest");
const planText = await page.textContent("#journeyStrip");
await check("plan destination is the pub", async () => planText.includes("BrewDog Lothian Road"));
await check("plan carries the partner pill", async () => planText.includes("Book a table"));
await check("partner link goes to OpenTable", async () => {
  const href = await page.getAttribute("#journeyStrip .plan-buy-inline", "href");
  return href && href.startsWith("https://www.opentable.co.uk/s?") && href.includes("latitude=55.947");
});
await check("place pin is on the map", async () => Boolean(await page.$(".gpin--selected")));
await check("show list is constrained by the place", async () =>
  (await page.textContent("#showsTitle")).includes("you can slip in before"));
await check("Maps route targets the pub's coords", async () => {
  const href = await page.getAttribute("#mapsRouteLink", "href");
  return href && href.includes(encodeURIComponent("55.9474969,-3.2065848"));
});
await page.screenshot({ path: `${SCRATCH}/shot-2-plan-pub.png`, fullPage: false });

// --- single-candidate auto-commit: Edinburgh Waverley (5 hits dedupe to 1) ---
await page.click("#journeyStrip .plan-node.dest .chg-link"); // Change ▾ reopens the editor
await page.fill("#destInput", "Edinburgh Waverley");
await page.press("#destInput", "Enter");
await page.waitForFunction(() =>
  document.querySelector("#journeyStrip")?.textContent.includes("Edinburgh Waverley"));
const trainText = await page.textContent("#journeyStrip");
await check("train commitment auto-commits (no picker)", async () => trainText.includes("Edinburgh Waverley"));
await check("train partner pill present", async () => trainText.includes("Train times"));
await check("train link goes to Trainline (plain until affiliate IDs set)", async () => {
  const href = await page.getAttribute("#journeyStrip .plan-buy-inline", "href");
  return href === "https://www.thetrainline.com/";
});
await page.screenshot({ path: `${SCRATCH}/shot-3-plan-train.png` });

// --- nothing-found fallback: keep as a note ---
await page.click("#journeyStrip .plan-node.dest .chg-link");
await page.fill("#destInput", "My cousin's flat");
await page.click("#destFind");
await page.waitForSelector("#destResults .place-hit--note");
await check("no-result message offers the note fallback", async () =>
  (await page.textContent("#destResults .place-msg")).includes("Couldn’t find"));
await page.screenshot({ path: `${SCRATCH}/shot-4-note-fallback.png` });
await page.click("#destResults .place-hit--note");
await check("note commitment recorded on the card, no partner pill", async () => {
  const card = await page.textContent('[data-value="constraint"]');
  return card.includes("My cousin's flat") && !(await page.$("#journeyStrip .plan-buy-inline"));
});

await browser.close();
console.log(process.exitCode ? "FLOW HAD FAILURES" : "FLOW OK");

