1	/* Non-show places — the "Not a show? Type a place" commitment.
2	 *
3	 * Everything here is pure (no DOM, no fetch): js/app.js does the fetching and
4	 * rendering, and js/__tests__/places.test.mjs exercises this module directly.
5	 *
6	 * Two jobs:
7	 *   1. Geocoding — build the Nominatim (OpenStreetMap's geocoder) search URL,
8	 *      bounded to Edinburgh, and normalize its results. Nominatim needs no API
9	 *      key, matching the site's Leaflet + OSM setup; its usage policy asks for
10	 *      an identifying Referer (the browser sends one) and ≤1 request/second
11	 *      (we only search on an explicit button press).
12	 *   2. Partner links — a booking link for the kinds of place people type
13	 *      (a restaurant table, train tickets, a hotel, an attraction), which
14	 *      becomes a referral link once the affiliate IDs below are filled in.
15	 */
16	
17	/* Bounding box for the geocoder: greater Edinburgh, Airport to Musselburgh.
18	 * Passed to Nominatim as a ranking bias and applied again client-side in
19	 * parsePlaces, so "Malmaison" can't resolve to the one in Newcastle.
20	 *
21	 * Deliberately NOT sent with `bounded=1`: probed against the live API
22	 * (2026-07-29), bounded restricts the search to amenity-tag matching inside
23	 * the box — "Waverley station" then returns the pub and café inside the
24	 * concourse but not Edinburgh Waverley itself, and "The Piemaker" returns
25	 * nothing. Unbounded search with the viewbox finds both; we drop any
26	 * out-of-box hits ourselves. */
27	export const EDINBURGH_VIEWBOX = { minLat: 55.87, maxLat: 56.0, minLng: -3.46, maxLng: -3.02 };
28	
29	/* Is a [lat, lng] inside the Edinburgh box above? */
30	export function inEdinburgh([lat, lng]) {
31	  const { minLat, maxLat, minLng, maxLng } = EDINBURGH_VIEWBOX;
32	  return lat >= minLat && lat <= maxLat && lng >= minLng && lng <= maxLng;
33	}
34	
35	/* ---------- Monetization: affiliate / referral IDs ----------
36	 *
37	 * These are NOT secrets — they ship in the client, like the analytics token in
38	 * js/analytics.js — and they are empty by default: every link below works as a
39	 * plain deep link, and starts tagging referrals the moment an ID is filled in.
40	 *
41	 * TO MONETIZE, join the partner programmes and paste the IDs here:
42	 *   - Awin (awin.com) — one publisher account covers Trainline (and many other
43	 *     UK travel/dining merchants). awinAffiliateId is your publisher ID;
44	 *     trainlineAwinMid is Trainline's advertiser ID from your Awin dashboard.
45	 *   - OpenTable (opentable.com/affiliate-program) — opentableRef is the `ref`
46	 *     value OpenTable assigns you.
47	 *   - Booking.com (partners.booking.com) — bookingAid is your `aid` number.
48	 *   - GetYourGuide (partner.getyourguide.com) — gygPartnerId.
49	 * A link whose programme IDs are unset simply stays untagged — partial set-up
50	 * is fine.
51	 */
52	export const AFFILIATES = {
53	  awinAffiliateId: "",
54	  trainlineAwinMid: "",
55	  opentableRef: "",
56	  bookingAid: "",
57	  gygPartnerId: "",
58	};
59	
60	/* Nominatim search URL for a free-text place query, bounded to Edinburgh.
61	 * jsonv2 gives each hit a `name`, a `category`/`type` pair (how we bucket the
62	 * place) and, with addressdetails, the street for the "which one?" line. */
63	export function geocodeUrl(query) {
64	  const { minLat, maxLat, minLng, maxLng } = EDINBURGH_VIEWBOX;
65	  const params = new URLSearchParams({
66	    q: query,
67	    format: "jsonv2",
68	    limit: "5",
69	    addressdetails: "1",
70	    // viewbox is two opposite lng,lat corners.
71	    viewbox: `${minLng},${maxLat},${maxLng},${minLat}`,
72	  });
73	  return `https://nominatim.openstreetmap.org/search?${params}`;
74	}
75	
76	/* Bucket a Nominatim category/type pair into the kinds the app knows how to
77	 * present (icon) and monetize (partner link). Anything unrecognized — a street
78	 * address, a shop, a park — is "other": still a fine destination, just with a
79	 * plain pin and no booking link. */
80	export function placeKind(category, type) {
81	  if (category === "railway") {
82	    // "stop" nodes are platforms of the same station (probed: Edinburgh
83	    // Waverley returns station + stop entries side by side).
84	    return type === "station" || type === "halt" || type === "stop" ? "train" : "other";
85	  }
86	  // Waverley's building outline is category "building", type "train_station".
87	  if (category === "building") {
88	    return type === "train_station" ? "train" : "other";
89	  }
90	  if (category === "amenity") {
91	    if (type === "restaurant" || type === "food_court" || type === "biergarten") return "restaurant";
92	    if (type === "cafe" || type === "fast_food" || type === "ice_cream") return "cafe";
93	    if (type === "pub" || type === "bar" || type === "nightclub") return "pub";
94	    // Arts centres (e.g. Summerhall) are Fringe venues in all but name.
95	    if (type === "theatre" || type === "arts_centre") return "theatre";
96	    // OSM types Camera Obscura — the attraction — as its own amenity.
97	    if (type === "camera_obscura" || type === "planetarium") return "attraction";
98	    return "other";
99	  }
100	  if (category === "tourism") {
101	    if (type === "hotel" || type === "hostel" || type === "guest_house" || type === "apartment")
102	      return "hotel";
103	    if (
104	      type === "museum" ||
105	      type === "attraction" ||
106	      type === "gallery" ||
107	      type === "viewpoint" ||
108	      type === "zoo" ||
109	      type === "theme_park"
110	    )
111	      return "attraction";
112	    return "other";
113	  }
114	  if (category === "historic") return "attraction";
115	  return "other";
116	}
117	
118	const PLACE_ICONS = {
119	  restaurant: "🍽️",
120	  cafe: "☕",
121	  pub: "🍺",
122	  train: "🚆",
123	  hotel: "🛏️",
124	  attraction: "🏛️",
125	  theatre: "🎭",
126	  other: "📍",
127	};
128	
129	export function placeIcon(kind) {
130	  return PLACE_ICONS[kind] || PLACE_ICONS.other;
131	}
132	
133	/* One OSM landmark often geocodes as several same-named hits a few dozen
134	 * metres apart (probed: Edinburgh Waverley = station node + building outline +
135	 * two platform stops). Treat same label within roughly a city block as one
136	 * place — and when the kept hit is an untyped "other" (a street, a roof), let
137	 * a typed duplicate (the station, the arts centre) take its slot. */
138	const NEARBY_LAT = 0.004; // ~440 m
139	const NEARBY_LNG = 0.006; // ~370 m at Edinburgh's latitude
140	
141	/* Normalize a Nominatim jsonv2 response into the places the app works with:
142	 * { label, area, lat, lng, kind }. Hits without usable coordinates or a name
143	 * are dropped rather than guessed at, and — since the search is deliberately
144	 * unbounded (see EDINBURGH_VIEWBOX) — so is anything outside Edinburgh. */
145	export function parsePlaces(json) {
146	  if (!Array.isArray(json)) return [];
147	  const hits = json
148	    .map((hit) => {
149	      const lat = parseFloat(hit.lat);
150	      const lng = parseFloat(hit.lon);
151	      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
152	      if (!inEdinburgh([lat, lng])) return null;
153	      const label = hit.name || String(hit.display_name || "").split(",")[0].trim();
154	      if (!label) return null;
155	      const addr = hit.address || {};
156	      // A short "which one?" disambiguator — the street beats the suburb.
157	      const area = addr.road || addr.neighbourhood || addr.suburb || "";
158	      return { label, area, lat, lng, kind: placeKind(hit.category, hit.type) };
159	    })
160	    .filter(Boolean);
161	
162	  const out = [];
163	  for (const hit of hits) {
164	    const dup = out.find(
165	      (kept) =>
166	        kept.label === hit.label &&
167	        Math.abs(kept.lat - hit.lat) <= NEARBY_LAT &&
168	        Math.abs(kept.lng - hit.lng) <= NEARBY_LNG
169	    );
170	    if (!dup) out.push(hit);
171	    else if (dup.kind === "other" && hit.kind !== "other") Object.assign(dup, hit);
172	  }
173	  return out;
174	}
175	
176	/* Awin deep-link wrapper: routes a merchant URL through the affiliate network
177	 * so the click is credited. Only meaningful once both IDs are set. */
178	function awinWrap(merchantId, affiliateId, url) {
179	  return (
180	    "https://www.awin1.com/cread.php" +
181	    `?awinmid=${encodeURIComponent(merchantId)}` +
182	    `&awinaffid=${encodeURIComponent(affiliateId)}` +
183	    `&ued=${encodeURIComponent(url)}`
184	  );
185	}
186	
187	/* The booking link for a place, or null for kinds with nothing sensible to
188	 * book. Returns { text, partner, url } — the caller renders "text · partner".
189	 * `affiliates` is injectable for tests; callers use the shipped config. */
190	export function partnerLink(place, affiliates = AFFILIATES) {
191	  const { label, lat, lng, kind } = place;
192	
193	  if (kind === "restaurant" || kind === "cafe" || kind === "pub") {
194	    let url =
195	      "https://www.opentable.co.uk/s" +
196	      `?term=${encodeURIComponent(label)}` +
197	      `&latitude=${encodeURIComponent(lat)}&longitude=${encodeURIComponent(lng)}`;
198	    if (affiliates.opentableRef) url += `&ref=${encodeURIComponent(affiliates.opentableRef)}`;
199	    return { text: "Book a table", partner: "OpenTable", url };
200	  }
201	
202	  if (kind === "train") {
203	    const base = "https://www.thetrainline.com/";
204	    const wrapped =
205	      affiliates.awinAffiliateId && affiliates.trainlineAwinMid
206	        ? awinWrap(affiliates.trainlineAwinMid, affiliates.awinAffiliateId, base)
207	        : base;
208	    return { text: "Train times & tickets", partner: "Trainline", url: wrapped };
209	  }
210	
211	  if (kind === "hotel") {
212	    let url =
213	      "https://www.booking.com/searchresults.html" +
214	      `?ss=${encodeURIComponent(`${label}, Edinburgh`)}`;
215	    if (affiliates.bookingAid) url += `&aid=${encodeURIComponent(affiliates.bookingAid)}`;
216	    return { text: "Check availability", partner: "Booking.com", url };
217	  }
218	
219	  if (kind === "attraction") {
220	    let url = `https://www.getyourguide.com/s/?q=${encodeURIComponent(`${label} Edinburgh`)}`;
221	    if (affiliates.gygPartnerId) url += `&partner_id=${encodeURIComponent(affiliates.gygPartnerId)}`;
222	    return { text: "Book tickets & tours", partner: "GetYourGuide", url };
223	  }
224	
225	  return null; // "theatre" and "other": a destination, not a booking
226	}
