  state.destLabel = "";
  state.destPlace = null;
  state.destNote = "";
  clearPlaceResults();
  state.showCap = SHOW_PAGE;
  syncDestInput();
  renderConstraintShows(true);
  refreshConstraintValue();
  refreshMap();
}

/* Commit a show as the next commitment, then close the picker to reveal the
