+
+  // The night maths must survive a month boundary.
+  const monthEnd = partnerLink(hotel, NO_IDS, { dateISO: "2026-08-31", time: "22:00" }).url;
+  assert.match(monthEnd, /checkin=2026-08-31/);
+  assert.match(monthEnd, /checkout=2026-09-01/);
