+    trainlineCamref: "1101lAbCdEf", // Trainline's programme runs on Partnerize (camref links)
+    awinAffiliateId: "123456", //       Booking.com's programme runs on Awin
+    bookingAwinMid: "18119",
+    gygPartnerId: "ABCDE",
+  };
