  cafe: "☕",
  pub: "🍺",
  train: "🚆",
  hotel: "🛏️",
  attraction: "🏛️",
  theatre: "🎭",
  other: "📍",
};

export function placeIcon(kind) {
  return PLACE_ICONS[kind] || PLACE_ICONS.other;
