    if (affiliates.gygPartnerId) url += `&partner_id=${encodeURIComponent(affiliates.gygPartnerId)}`;
    return { text: "Book tickets & tours", partner: "GetYourGuide", url };
  }

  return null; // "theatre" and "other": a destination, not a booking
