+.plan-book-btn { display: block; text-align: center; font-size: 0.95rem; font-weight: 800; text-decoration: none; padding: 12px 16px; border-radius: 12px; color: #fff; background: var(--red); }
+.plan-book-btn:hover { background: var(--red-dark); }
+.plan-book-btn:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }

 /* Hairline between the top actionable card (plan, or the CTA before one
    exists) and the browse section (shows title, filters, map, list). */

