// Drive the Now page's "Not a show? Type a place" flow in real Chromium.
// External hosts are blocked in this sandbox, so every third-party request is
// route-intercepted: Leaflet from the local npm copies, tiles/fonts aborted,
// and Nominatim answered from the SAME committed fixtures the unit tests use —
// so the browser exercises the shipped fetch path deterministically.
import { chromium } from "playwright-core";
import { readFileSync } from "node:fs";

const REPO = "/home/user/EdFringeNow";
const SCRATCH = "/tmp/claude-0/-home-user-EdFringeNow/61bd45c2-d6e6-548c-a167-be9f0ac03147/scratchpad";
const fixture = (n) => readFileSync(`${REPO}/js/__tests__/fixtures/nominatim/${n}.json`, "utf8");

const browser = await chromium.launch({
  executablePath: "/opt/pw-browsers/chromium-1194/chrome-linux/chrome",
  args: ["--no-sandbox"],
});
const page = await browser.newPage({ viewport: { width: 480, height: 1000 } });
page.setDefaultTimeout(15000);

const local = {
  "leaflet@1.9.4/dist/leaflet.js": `${SCRATCH}/node_modules/leaflet/dist/leaflet.js`,
  "leaflet@1.9.4/dist/leaflet.css": `${SCRATCH}/node_modules/leaflet/dist/leaflet.css`,
  "leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js": `${SCRATCH}/node_modules/leaflet.markercluster/dist/leaflet.markercluster.js`,
  "leaflet.markercluster@1.5.3/dist/MarkerCluster.css": `${SCRATCH}/node_modules/leaflet.markercluster/dist/MarkerCluster.css`,
};
await page.route("https://unpkg.com/**", (route) => {
  const hit = Object.entries(local).find(([k]) => route.request().url().includes(k));
  if (!hit) return route.abort();
  const type = hit[0].endsWith(".css") ? "text/css" : "application/javascript";
  route.fulfill({ body: readFileSync(hit[1], "utf8"), contentType: type });
});
await page.route("https://fonts.googleapis.com/**", (r) => r.abort());
await page.route("https://fonts.gstatic.com/**", (r) => r.abort());
await page.route("https://*.tile.openstreetmap.org/**", (r) => r.abort());
await page.route("https://nominatim.openstreetmap.org/search*", (route) => {
  const q = new URL(route.request().url()).searchParams.get("q") || "";
  const body = /brewdog/i.test(q) ? fixture("brewdog")
    : /waverley/i.test(q) ? fixture("edinburgh-waverley")
    : fixture("zzzqqqxyzzy");
  route.fulfill({ body, contentType: "application/json" });
});

