60	/* Nominatim search URL for a free-text place query, bounded to Edinburgh.
61	 * jsonv2 gives each hit a `name`, a `category`/`type` pair (how we bucket the
62	 * place) and, with addressdetails, the street for the "which one?" line. */
63	export function geocodeUrl(query) {
64	  const { minLat, maxLat, minLng, maxLng } = EDINBURGH_VIEWBOX;
65	  const params = new URLSearchParams({
66	    q: query,
67	    format: "jsonv2",
68	    limit: "5",
69	    addressdetails: "1",
70	    // viewbox is two opposite lng,lat corners.
71	    viewbox: `${minLng},${maxLat},${maxLng},${minLat}`,
72	  });
73	  return `https://nominatim.openstreetmap.org/search?${params}`;
74	}
